using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Freyja.Prototype;
public static class TestDoors023 {
 class Entry{public string id;public Vector3 door,road;public Vector3[] points;}
 const string Folder="/Users/bruno.duartec/Documents/Projects/Freyja/Artifacts/Island023/";
 static EditorApplication.CallbackFunction tick;
 public static object Main(){var entries=Newtonsoft.Json.JsonConvert.DeserializeObject<List<Entry>>(File.ReadAllText(Folder+"access-layout.json"));var player=GameObject.Find("PlayerPrototype").GetComponent<CaisPlayerController>();var session=GameObject.Find("Cais Session").GetComponent<CaisSessionController>();session.enabled=false;player.ControlEnabled=true;var cam=GameObject.Find("Cais Gameplay Camera").GetComponent<Camera>();var terrain=GameObject.Find("Island023").GetComponentInChildren<Terrain>();var results=new List<object>();int index=0,way=1;float begin=0,started=Time.realtimeSinceStartup;bool waiting=true;Time.timeScale=2;Directory.CreateDirectory(Folder+"doors");
 Action reset=()=>{var p=entries[index].road;p.y=terrain.SampleHeight(p)+terrain.transform.position.y+.15f;player.Body.enabled=false;player.transform.position=p;player.Body.enabled=true;way=1;begin=Time.realtimeSinceStartup;waiting=true;};reset();
 tick=()=>{try{if(!EditorApplication.isPlaying){EditorApplication.update-=tick;return;}float now=Time.realtimeSinceStartup;if(now-begin<.35f){player.SetMoveInput(Vector2.zero);return;}waiting=false;var entry=entries[index];var p=player.transform.position;var target=entry.points[Mathf.Min(way,entry.points.Length-1)];var delta=Vector3.ProjectOnPlane(target-p,Vector3.up);if(delta.magnitude<.35f&&way<entry.points.Length-1){way++;target=entry.points[way];delta=Vector3.ProjectOnPlane(target-p,Vector3.up);}bool done=way==entry.points.Length-1&&delta.magnitude<.38f;bool timeout=now-begin>13;var f=Vector3.ProjectOnPlane(cam.transform.forward,Vector3.up).normalized;var r=Vector3.ProjectOnPlane(cam.transform.right,Vector3.up).normalized;var direction=delta.normalized;player.SetMoveInput(done||timeout?Vector2.zero:new Vector2(Vector3.Dot(direction,r),Vector3.Dot(direction,f)));
 if(done||timeout){var finalDelta=Vector3.ProjectOnPlane(entry.door-p,Vector3.up).magnitude;float heightError=Mathf.Abs(p.y-entry.door.y);bool pass=done&&heightError<.5f;results.Add(new{id=entry.id,passed=pass,reached=done,grounded=player.Body.isGrounded,distance=finalDelta,heightError,seconds=now-begin,x=p.x,y=p.y,z=p.z,waypoint=way});var rt=cam.targetTexture;var tex=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);var old=RenderTexture.active;RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);tex.Apply();File.WriteAllBytes(Folder+"doors/"+index.ToString("D2")+".png",tex.EncodeToPNG());RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(tex);File.WriteAllText(Folder+"doors-progress.json",Newtonsoft.Json.JsonConvert.SerializeObject(results,Newtonsoft.Json.Formatting.Indented));index++;if(index==entries.Count){EditorApplication.update-=tick;Time.timeScale=1;File.WriteAllText(Folder+"doors-result.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{seconds=now-started,tests=results},Newtonsoft.Json.Formatting.Indented));return;}reset();}
 }catch(Exception ex){player.SetMoveInput(Vector2.zero);Time.timeScale=1;EditorApplication.update-=tick;File.WriteAllText(Folder+"doors-error.txt",ex.ToString());}};EditorApplication.update+=tick;return "17 testes de acesso iniciados: controlador real, rua até porta, sem teleporte durante cada percurso.";}
}
